def envelope(value):
    return followup.BEGIN + base64.b64encode(json.dumps(value).encode()).decode() + followup.END


class ResultContractTests(unittest.TestCase):
    def test_new_request_requires_correlated_final_result_without_changing_historical_prompt(self):
        api = fixtures.CloudAuthority()
        value = control()
        execution.prepare(api, lambda: deepcopy(value))
        record = api.ledger["workItems"][0]
        assignment = record["assignments"][0]
        self.assertEqual(2, assignment["execution"]["request_version"])
        prompt = execution.request(api, record, assignment)["prompt"]
        self.assertIn("CSWORKITEMBEGIN", prompt)
        self.assertIn("stop without a PR", prompt)
        historical = deepcopy(assignment)
        historical["execution"].pop("request_version")
        self.assertNotIn("CSWORKITEMBEGIN", execution.request(api, record, historical)["prompt"])

    def test_result_envelope_requires_exact_attribution_and_one_complete_json(self):
        import work_item_followup as followup
        assignment = {"id": "assignment", "revision": 1}
        record = {"id": "example-item"}
        claimed = result(assignment)
        text = envelope(claimed)
        self.assertEqual(claimed, followup.parse_result(text, record, assignment, "session-1"))
        for bad in ("no final JSON", text + text, envelope(dict(claimed, assignment_id="foreign")),
                    "CSWORKITEMBEGIN{}CSWORKITEMEND", envelope(dict(claimed, schema_version=True))):
            with self.subTest(text=bad), self.assertRaises(ValueError):
                followup.parse_result(bad, record, assignment, "session-1")

    def test_bounded_historical_session_log_over_100kb_is_scanned_for_result_envelope(self):
        assignment = {"id": "assignment", "revision": 1}
        with self.assertRaisesRegex(ValueError, "missing or conflicting worker result JSON"):
            followup.parse_result(
                "x" * 100_001,
                {"id": "example-item"},
                assignment,
                "session-1")

    def test_renderer_wrapped_base64_roundtrips_multiword_strings_but_raw_json_is_not_accepted(self):
        assignment = {"id": "assignment", "revision": 1}
        claimed = result(assignment)
        claimed["summary"] = "This is a long multiword result summary " * 15
        text = envelope(claimed)
        # gh's non-TTY Markdown renderer can insert whitespace at wrap points.
        payload = text[len(followup.BEGIN):-len(followup.END)]
        rendered = "\n  " + followup.BEGIN + "\n    " + "\n    ".join(
            payload[index:index + 80] for index in range(0, len(payload), 80)) + "\n" + followup.END + "\n"
        self.assertEqual(claimed, followup.parse_result(rendered, {"id": "example-item"}, assignment, "session-1"))
        # Generated by the actual Glamour v0.10.0 renderer with gh 2.102.0's
        # non-TTY 80-column options, not a fabricated raw transcript.
        fixture = Path(__file__).parent / "fixtures" / "work-item-rendered-result.json"
        rendered_fixture = json.loads(fixture.read_text())["rendered"]
        self.assertEqual(claimed, followup.parse_result(
            rendered_fixture, {"id": "example-item"}, assignment, "session-1"))
        with self.assertRaises(ValueError):
            followup.parse_result(followup.BEGIN + json.dumps(claimed) + followup.END,
                                  {"id": "example-item"}, assignment, "session-1")

    def test_renderer_output_with_foreign_or_corrupted_payload_cannot_checkpoint(self):
        fixture = Path(__file__).parent / "fixtures" / "work-item-rendered-result.json"
        rendered = json.loads(fixture.read_text())["rendered"]
        for bad in (rendered + rendered, rendered.replace("eyJ", "!yJ", 1),
                    envelope(dict(result({"id": "foreign", "revision": 1}), worker_id="session-1"))):
            with self.subTest(text=bad), self.assertRaises(ValueError):
                followup.parse_result(bad, {"id": "example-item"}, {"id": "assignment", "revision": 1}, "session-1")


class CollectionTests(unittest.TestCase):
    def setUp(self):
        # Reuse the actual authenticated transport/ledger fixture, not a mock
        # checkpoint implementation.
        fixture = fixtures.MappingTests()
        fixture.setUp()
        self.addCleanup(fixture.doCleanups)
        self.api, self.control, self.task = fixture.api, fixture.control, fixture.task
        self.read = fixture.read
        self.assignment = fixture.assignment
        self.task["artifacts"] = []
        fixture.transport.values.update({
            fixture.prefix + "/actions/runs/100/attempts/1": {
                "id": 100, "run_attempt": 1, "head_sha": "a" * 40},
            fixture.prefix + "/actions/jobs/200": {
                "id": 200, "run_id": 100, "run_attempt": 1,
                "head_sha": "a" * 40, "conclusion": "failure"},
        })
        self.transport = fixture.transport

    def logs(self, *_):
        claimed = result(self.assignment)
        claimed.update(worker_id="SESSION1", outcome="no_fix", changed_files=[],
                       pr_proposal=None, summary="No justified fix.", actual_classification="inconclusive")
        return envelope(claimed)

    def test_no_pr_result_checkpoints_exact_session_and_previews_only(self):
        receipt = followup.collect(self.api, self.read, self.logs)
        self.assertEqual("checkpointed", receipt["outcome"])
        assignment = self.api.ledger["workItems"][0]["assignments"][0]
        self.assertEqual("SESSION1", assignment["result"]["worker_id"])
        self.assertEqual("no_fix", assignment["result"]["outcome"])
        preview = followup.report(self.api, self.read)
        self.assertEqual("human_wait", preview["outcome"])
        self.assertIn("@radical", preview["comment_preview"])
        self.assertEqual([], self.api.ledger["chains"])
        self.assertTrue(all(method == "PATCH" for method, _, _ in self.transport.writes))

    def test_unavailable_json_preserves_separate_host_assessment_and_never_synthesizes_result(self):
        receipt = followup.collect(self.api, self.read, lambda *_: "Completed with no changes.")
        self.assertEqual("unavailable", receipt["outcome"])
        assignment = self.api.ledger["workItems"][0]["assignments"][0]
        self.assertIsNone(assignment["result"])
        self.assertIn("Worker final JSON unavailable", followup.report(self.api, self.read)["comment_preview"])

    def test_interrupted_third_collection_recovers_unavailable_without_another_log_read(self):
        calls = []
        def interrupted(*_):
            calls.append(1)
            raise KeyboardInterrupt()
        for _ in range(3):
            with self.assertRaises(KeyboardInterrupt):
                followup.collect(self.api, self.read, interrupted)
        receipt = followup.collect(self.api, self.read, interrupted)
        self.assertEqual("unavailable", receipt["outcome"])
        self.assertEqual(3, len(calls))
        self.assertEqual("unavailable", followup.collect(self.api, self.read, interrupted)["outcome"])
        self.assertEqual(3, len(calls))
        self.assertEqual("unavailable", self.api.ledger["workItems"][0]["assignments"][0]
                         ["execution"]["followup"]["status"])
        self.assertEqual("human_wait", followup.report(self.api, self.read, publish=True)["outcome"])
        self.assertTrue(all(method == "PATCH" for method, _, _ in self.transport.writes))

    def test_resumption_during_collection_never_checkpoints(self):
        def resumed(*args):
            value = self.logs(*args)
            self.task["state"] = self.task["sessions"][0]["state"] = "in_progress"
            return value
        self.assertEqual("unavailable", followup.collect(self.api, self.read, resumed)["outcome"])
        self.assertIsNone(self.api.ledger["workItems"][0]["assignments"][0]["result"])

    def test_missing_malformed_conflicting_json_and_unavailable_logs_never_become_worker_results(self):
        for log in ("", "CSWORKITEMBEGIN{}CSWORKITEMEND", self.logs() + self.logs()):
            with self.subTest(log=log):
                receipt = followup.collect(self.api, self.read, lambda *_: log)
                self.assertEqual("unavailable", receipt["outcome"])
                self.assertIsNone(self.api.ledger["workItems"][0]["assignments"][0]["result"])
        with patch.object(self.api.transport, "writes", []):
            receipt = followup.collect(self.api, self.read, lambda *_: self.logs())
        self.assertEqual("unavailable", receipt["outcome"])

    def test_unavailable_logs_are_explicit_and_secrets_not_checkpointed(self):
        def unavailable(*_):
            raise CollectionError("authentication")
        receipt = followup.collect(self.api, self.read, unavailable, assessment={
            "summary": "No fix justified.", "evidence": ["token=ghp_unsafe https://storage.invalid/?sig=secret"],
            "unknowns": ["Feed transience unknown."]})
        self.assertEqual("unavailable", receipt["outcome"])
        body = followup.report(self.api, self.read)["comment_preview"]
        self.assertIn("authentication", body)
        self.assertNotIn("ghp_unsafe", body)
        self.assertNotIn("storage.invalid", body)
        self.assertIn("Operator-attributed", body)

    def test_changed_session_or_control_during_collection_cannot_checkpoint(self):
        def changed(*args):
            value = self.logs(*args)
            self.task["sessions"][0]["id"] = "FOREIGN"
            return value
        self.assertEqual("unavailable", followup.collect(self.api, self.read, changed)["outcome"])
        self.assertIsNone(self.api.ledger["workItems"][0]["assignments"][0]["result"])
        self.assertIsNone(self.api.ledger["workItems"][0]["assignments"][0]["execution"]["task_state"])

    def test_false_permission_preview_closed_empty_draft_and_no_import(self):
        self.task["artifacts"] = [
            {"provider": "github", "type": "pull", "data": {"id": 1007}},
            {"provider": "github", "type": "branch", "data": {"head_ref": "fix-7", "base_ref": "main"}}]
        self.transport.values["repos/radical/aspire/pulls/7"].update(state="closed", commits=0)
        followup.collect(self.api, self.read, self.logs)
        self.assertEqual("human_wait", followup.report(self.api, self.read, publish=True)["outcome"])
        self.assertEqual([], self.api.ledger["chains"])
        self.assertTrue(all(method == "PATCH" for method, _, _ in self.transport.writes))

    def test_pause_hands_off_disabled_and_stale_source_deny_followup(self):
        followup.collect(self.api, self.read, self.logs)
        for mode in ("pause", "hands-off", "disabled", "source"):
            with self.subTest(mode=mode):
                manager = patch.object(self.api, "enabled", return_value=False) if mode == "disabled" else (
                    patch.object(fixtures.local, "require_source", side_effect=ValueError("stale"))
                    if mode == "source" else fixtures.nullcontext())
                if mode == "pause":
                    self.control.update(revision=2, action="pause")
                if mode == "hands-off":
                    self.transport.values["repos/radical/aspire/issues/900"]["labels"] = [
                        {"name": "shepherd-hands-off"}]
                with manager, self.assertRaises(ValueError):
                    followup.report(self.api, self.read, publish=True)
                self.control.update(revision=1, action="run")
                self.transport.values["repos/radical/aspire/issues/900"]["labels"] = []

    def test_new_version_correlation_cannot_verify_historical_session_and_vice_versa(self):
        self.task["sessions"][0]["prompt"] = "ci-shepherd-work-item: unbound"
        with self.assertRaises(ValueError):
            followup.collect(self.api, self.read, self.logs)
        self.assertIsNone(self.api.ledger["workItems"][0]["assignments"][0]["result"])

    def test_historical_task_without_result_contract_remains_verifiable_but_json_unavailable(self):
        self.assignment["execution"].pop("request_version")
        self.assignment.pop("request_version")
        self.task["sessions"][0]["prompt"] = execution.request(
            self.api, self.api.ledger["workItems"][0], self.assignment)["prompt"]
        self.api.persist()
        self.assertEqual("unavailable", followup.collect(
            self.api, self.read, lambda *_: "Historical worker narrative; no final result envelope.")["outcome"])
        self.assertIsNone(self.api.ledger["workItems"][0]["assignments"][0]["result"])
        self.assertEqual("human_wait", followup.report(self.api, self.read)["outcome"])

    def test_completed_task_freshness_change_or_stale_control_prevents_checkpoint(self):
        self.task["updated_at"] = "2026-10-09T00:00:00Z"
        def changed(*args):
            value = self.logs(*args)
            self.task["updated_at"] = "2026-10-09T00:01:00Z"
            return value
        self.assertEqual("unavailable", followup.collect(self.api, self.read, changed)["outcome"])
        self.assertIsNone(self.api.ledger["workItems"][0]["assignments"][0]["result"])
        def paused(*args):
            value = self.logs(*args)
            self.control.update(revision=2, action="pause")
            return value
        with self.assertRaises(ValueError):
            followup.collect(self.api, self.read, paused)
        canonical = self.api.read_authority()["workItems"][0]["assignments"][0]
        self.assertIsNone(canonical["result"])

    def test_worker_requested_foreign_comment_is_only_a_denied_proposal(self):
        def logs(*args):
            claim = followup.parse_result(self.logs(*args), {"id": "example-item"}, self.assignment, "SESSION1")
            claim["proposed_actions"] = [{
                "kind": "comment_issue", "target": {"repository": "microsoft/aspire", "number": 901, "node_id": "OTHER"},
                "title": "Update", "body": "Claimed diagnosis.", "evidence": [],
                "justification": "Unverified request", "test_identity": None}]
            return envelope(claim)
        followup.collect(self.api, self.read, logs)
        self.assertIn("denied: target outside owned", followup.report(self.api, self.read)["comment_preview"])
        self.assertTrue(all(method == "PATCH" for method, _, _ in self.transport.writes))

    def test_real_post_comment_has_exact_canonical_receipt_and_reentry_sends_once(self):
        self.control["authority"]["issue_comment"] = True
        self.control["revision"] = 2
        followup.collect(self.api, self.read, self.logs)
        original = type(self.transport).__call__
        posted = []
        policy = work_item_github.FollowupTransport("fixture", 99, 500, self.control)
        def transport(instance, method, endpoint, body):
            if method == "POST":
                policy.validate_endpoint(method, endpoint, body)
                posted.append(body["body"])
                return fixtures.Response({"id": 42, "body": body["body"],
                                          "user": {"id": 1472, "login": "radical"}}, {}, 201)
            return original(instance, method, endpoint, body)
        with patch.object(type(self.transport), "__call__", transport):
            self.assertEqual("commented", followup.report(self.api, self.read, publish=True)["outcome"])
            self.assertEqual("human_wait", followup.report(self.api, self.read, publish=True)["outcome"])
        self.assertEqual(1, len(posted))

    def test_pinned_wrong_attempt_never_claims_diagnosis(self):
        self.transport.values["repos/radical/aspire/actions/jobs/200"]["run_attempt"] = 2
        receipt = followup.collect(self.api, self.read, self.logs)
        self.assertEqual("unavailable", receipt["outcome"])
        self.assertIn("pinned occurrence identity", receipt["reason"])
        self.assertIsNone(self.api.ledger["workItems"][0]["assignments"][0]["result"])

    def test_lost_comment_response_restart_recovers_owned_exact_body_once(self):
        self.control["authority"]["issue_comment"] = True
        self.control["revision"] = 2
        followup.collect(self.api, self.read, self.logs)
        followup.report(self.api, self.read)
        body = self.api.ledger["workItems"][0]["comment"]["body"]
        posts = []
        def lost(issue, text, guard):
            guard()
            posts.append(text)
            raise LostResponse("lost")
        with patch.object(self.api, "post_comment", side_effect=lost):
            self.assertEqual("comment_uncertain", followup.report(self.api, self.read, publish=True)["outcome"])
        # The subsequent call reloads canonical authority, as a restarted CLI does.
        with patch.object(self.api, "issue_comments", return_value=[
                {"id": 42, "body": body, "owned": True}]):
            self.assertEqual("human_wait", followup.report(self.api, self.read, publish=True)["outcome"])
            self.assertEqual("human_wait", followup.report(self.api, self.read, publish=True)["outcome"])
        self.assertEqual([body], posts)
        self.assertEqual(1, body.count("@radical"))

    def test_before_post_refresh_rejects_resumed_task_with_no_comment_send(self):
        self.control["authority"]["issue_comment"] = True
        self.control["revision"] = 2
        followup.collect(self.api, self.read, self.logs)
        posts = []
        def resumed(issue, body, guard):
            self.task["state"] = self.task["sessions"][0]["state"] = "in_progress"
            guard()
            posts.append(body)
            return 1
        with patch.object(self.api, "post_comment", side_effect=resumed), self.assertRaises(ValueError):
            followup.report(self.api, self.read, publish=True)
        self.assertEqual([], posts)


class TransportTests(unittest.TestCase):
    def test_followup_is_separate_from_cloud_launch_and_unrelated_effects(self):
        value = control()
        value["authority"]["issue_comment"] = True
        policy = work_item_github.FollowupTransport("fixture", 99, 500, value)
        policy.task_id = "TASK1"
        for path in ("agents/repos/radical/aspire/tasks/TASK1",
                     "repos/radical/aspire/actions/jobs/200",
                     "repos/radical/aspire/actions/runs/100/attempts/1"):
            policy.validate_endpoint("GET", path, None)
        for method, path in (("POST", "agents/repos/radical/aspire/tasks"),
                             ("POST", "repos/radical/aspire/issues"),
                             ("PATCH", "repos/radical/aspire/issues/900"),
                             ("GET", "agents/repos/radical/aspire/tasks/FOREIGN"),
                             ("GET", "repos/radical/aspire/actions/jobs/201")):
            with self.subTest(path=path), self.assertRaises(ValueError):
                policy.validate_endpoint(method, path, {})


class CollectorCompatibilityTests(unittest.TestCase):
    def test_only_audited_versions_use_exact_session_and_verified_keyring_for_logs(self):
        from result_collector import LocalCollector
        for version in ("2.101.0", "2.102.0", "2.103.0"):
            calls = []
            def command(argv, environment, **kwargs):
                calls.append((argv, environment))
                if argv == ["gh", "--version"]:
                    return 0, "gh version " + version + " (date)", ""
                if argv[:3] == ["gh", "auth", "token"]:
                    return 0, "selected", ""
                return 0, "assistant and tool rendered transcript", ""
            collector = LocalCollector("selected", command=command, environment={"GH_TOKEN": "not-selected"})
            if version == "2.103.0":
                with self.assertRaises(CollectionError):
                    collector("radical/aspire", "SESSION1")
                self.assertEqual(1, len(calls))
            else:
                self.assertEqual("assistant and tool rendered transcript", collector("radical/aspire", "SESSION1"))
                self.assertEqual(["gh", "agent-task", "view", "SESSION1", "-R", "radical/aspire", "--log"], calls[-1][0])
                self.assertTrue(all("GH_TOKEN" not in environment for _, environment in calls))


class UpstreamCollectionTests(unittest.TestCase):
    def test_verified_unimported_pr_revalidates_through_production_followup_policy(self):
        fixture = fixtures.UpstreamMappingTests()
        fixture.setUp()
        self.addCleanup(fixture.doCleanups)
        execution.observe(fixture.api, fixture.read)
        self.assertIsNotNone(fixture.api.ledger["workItems"][0]["assignments"][0]["execution"]["pr"])
        fixture.transport.values.update({
            "repos/microsoft/aspire/actions/runs/100/attempts/1": {
                "id": 100, "run_attempt": 1, "head_sha": "a" * 40},
            "repos/microsoft/aspire/actions/jobs/200": {
                "id": 200, "run_id": 100, "run_attempt": 1, "head_sha": "a" * 40}})
        api = work_item_github.FollowupGitHub(
            "fixture", 99, 500, "TRACKER99", revision="c" * 40,
            control=fixture.control, transport=fixture.transport)
        policy = work_item_github.FollowupTransport("fixture", 99, 500, fixture.control)
        fixture.transport.task_id = None
        fixture.transport.saved_pull = None
        original = type(fixture.transport).__call__
        def validated(instance, method, endpoint, body):
            policy.task_id = instance.task_id
            policy.saved_pull = instance.saved_pull
            policy.validate_endpoint(method, endpoint, body)
            return original(instance, method, endpoint, body)
        with patch.object(api, "enabled", return_value=True), \
                patch.object(type(fixture.transport), "__call__", validated):
            self.assertEqual("unavailable", followup.collect(api, fixture.read, lambda *_: "No result.")["outcome"])
            self.assertEqual("human_wait", followup.report(api, fixture.read, publish=True)["outcome"])
            self.assertEqual([], api.ledger["chains"])
            fixture.pull["id"] += 1
            with self.assertRaises(ValueError):
                followup.collect(api, fixture.read, lambda *_: self.fail("no log read after PR identity drift"))
        with self.assertRaises(ValueError):
            policy.validate_endpoint("GET", "repos/microsoft/aspire/pulls/8", None)

    def test_production_followup_transport_persists_upstream_attempt_preview_and_comment(self):
        fixture = fixtures.UpstreamMappingTests()
        fixture.setUp()
        self.addCleanup(fixture.doCleanups)
        fixture.control["revision"] = 2
        fixture.control["authority"]["issue_comment"] = True
        fixture.task["artifacts"] = []
        fixture.transport.values.update({
            "repos/microsoft/aspire/actions/runs/100/attempts/1": {
                "id": 100, "run_attempt": 1, "head_sha": "a" * 40},
            "repos/microsoft/aspire/actions/jobs/200": {
                "id": 200, "run_id": 100, "run_attempt": 1, "head_sha": "a" * 40},
        })
        policy = work_item_github.FollowupTransport("fixture", 99, 500, fixture.control)
        policy.task_id = "TASK1"
        original = type(fixture.transport).__call__
        posts = []
        def validated(instance, method, endpoint, body):
            policy.validate_endpoint(method, endpoint, body)
            if method == "POST":
                posts.append(body["body"])
                return fixtures.Response({"id": 42, "body": body["body"],
                                          "user": {"id": 1472, "login": "radical"}}, {}, 201)
            return original(instance, method, endpoint, body)
        api = work_item_github.FollowupGitHub("fixture", 99, 500, "TRACKER99", revision="c" * 40,
                                             control=fixture.control, transport=fixture.transport)
        with patch.object(api, "enabled", return_value=True), \
                patch.object(type(fixture.transport), "__call__", validated):
            self.assertEqual("unavailable", followup.collect(api, fixture.read, lambda *_: "No result.")["outcome"])
            self.assertEqual("human_wait", followup.report(api, fixture.read)["outcome"])
            self.assertEqual("commented", followup.report(api, fixture.read, publish=True)["outcome"])
            self.assertEqual("human_wait", followup.report(api, fixture.read, publish=True)["outcome"])
        self.assertEqual(1, len(posts))
        self.assertEqual("microsoft/aspire", fixtures.state.parse(fixture.transport.comments[0]["body"])["repository"])
        wrong = fixtures.state.render(fixtures.state.new_ledger("radical/aspire"))
        with self.assertRaises(ValueError):
            policy.validate_endpoint("PATCH", "repos/radical/aspire/issues/comments/500", {"body": wrong})
        changed = fixtures.state.parse(fixture.transport.comments[0]["body"])
        changed["workItems"][0]["control"]["scope"] = "Different pinned work"
        changed_body = fixtures.state.render(changed)
        with self.assertRaises(ValueError):
            policy.validate_endpoint("PATCH", "repos/radical/aspire/issues/comments/500",
                                     {"body": changed_body})

    def test_upstream_no_artifact_task_has_independent_preview_without_import_or_post(self):
        fixture = fixtures.UpstreamMappingTests()
        fixture.setUp()
        self.addCleanup(fixture.doCleanups)
        fixture.task["artifacts"] = []
        prefix = "repos/microsoft/aspire/actions"
